window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["3c"]={"https://www.gov.uk/foreign-travel-advice/belgium":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"2081a56f356f750c9cca5f35d9b7b9379478a9a3a446455ff70ad01bea6d5282","read":"https://www.gov.uk/api/content/foreign-travel-advice/belgium","bytes":92971,"x":"fulltext v1","title":"Belgium travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-24T00:00:00+00:00","mod":"2026-10-17T20:49:24+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["National strike action"]},{"k":"p","s":["Strike action is an ongoing issue that can cause disruption."]},{"k":"p","s":["Monitor local news and check with your provider regarding potential delays and closures. Always check with your travel operator for the latest updates. Read more information about demonstrations and strikes on the ",["Safety and security page","https://www.gov.uk/foreign-travel-advice/belgium/safety-and-security"],"."]},{"k":"p","s":["General strikes took place on 31 March, 29 April,14 October, 26 November, 15 December 2025, 12 March, 12 May, 9 and 12 October 2026. Strike action may be announced at short notice."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/belgium/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Belgium set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Belgian Embassy in the UK","https://unitedkingdom.diplomatie.belgium.be/en"],"."]},{"k":"h","s":["Travelling through Calais"]},{"k":"p","s":["If you’re travelling through Calais, check the ",["travel advice for France","https://www.gov.uk/foreign-travel-advice/france"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Belgium follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the date you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Belgium, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The ",["requirements for working in Belgium","https://www.gov.uk/guidance/travel-to-belgium-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day visa-free limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Belgian border control, you may also need to:"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["show you have enough money for your stay"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, you must meet the Belgian government’s entry requirements. Check which type of visa or work permit you need with the ",["Belgian Embassy in the UK","https://unitedkingdom.diplomatie.belgium.be/en"],"."]},{"k":"p","s":["If you are in Belgium with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Belgium","https://www.gov.uk/guidance/living-in-belgium#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"]," and consult the ",["Belgian Immigration Office Website on EES","https://dofi.ibz.be/en/themes/entry/border-control/entry-exit-system-ees/faq"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Additional Border Controls in Belgium"]},{"k":"p","s":["Belgium has introduced additional entry checks until December 2025. Checks may be carried out on major roads leading into Belgium, motorway car parks, international bus services, international trains and on intra-Schengen flights. Checks may involve verifying travel documents and identification, as well as screening for illegal substances. In Belgium you must carry your passport with you at all times."]},{"k":"h","s":["Border controls at Germany’s land borders"]},{"k":"p","s":["There are temporary border controls in place to travel into Germany. Check the ",["entry requirements for Germany","https://www.gov.uk/foreign-travel-advice/germany/entry-requirements"],"."]},{"k":"h","s":["Border controls at the Netherlands’ land and air borders"]},{"k":"p","s":["The Netherlands has reintroduced temporary border controls at its land borders as well as additional checks on some international trains and specific flights, for a period of six months. See information from ",["Royal Netherlands Marechaussee","https://english.marechaussee.nl/topics/t/temporary-reintroduction-of-border-control"],"."]},{"k":"h","s":["Children aged 17 and under"]},{"k":"p","s":["Adults, including parents and guardians, who are travelling to or from Belgium with children aged 17 or under may have to provide proof of their relationship to the children they are accompanying. Carry a birth certificate or court order, particularly if you have a different surname to the children."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Belgium guide","https://travelhealthpro.org.uk/country/25/belgium#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods that can be brought into and taken out of Belgium","https://finance.belgium.be/en/customs_excises/private-individuals/travelling/bringing-back-foreign-goods-belgium"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food into Belgium"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into or out of Belgium"]},{"k":"p","s":["You must ",["complete a disclosure form","https://finance.belgium.be/en/customs_excises/private-individuals/travelling/movement-cash/to-or-from-eu"]," at customs if you’re carrying currency worth 10,000 euros or more."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Belgium"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Belgium."]},{"k":"p","s":["Terrorism attacks could be indiscriminate, including in places frequented by foreign nationals such as:"]},{"k":"li","s":["public transport"]},{"k":"li","s":["national and international transport hubs"]},{"k":"li","s":["music, sporting and cultural events"]},{"k":"li","s":["entertainment establishments and nightlife venues"]},{"k":"li","s":["government buildings and international institutions"]},{"k":"li","s":["places of worship and religious sites"]},{"k":"p","s":["You should be vigilant in public places and follow the advice of local authorities."]},{"k":"p","s":["There have been some high-profile terrorist attacks across Belgium. The main threat is from extremists linked to Daesh (formerly referred to as ISIL). Previous incidents have included fatal attacks against civilians and law enforcement:"]},{"k":"li","s":["on 16 October 2023, 2 people were killed and one seriously injured in a terrorism-related shooting incident in Brussels"]},{"k":"li","s":["in 2022, a police officer was killed and another injured in a suspected terrorist incident in Brussels"]},{"k":"p","s":["The Belgian authorities have successfully disrupted various attack plans, making a number of arrests in recent years. The Belgian government has set the national threat level at 3 ‘Serious’. You can expect to see an increased police presence, and additional safety measures may be in place. Be aware of your surroundings and follow the advice of local authorities."]},{"k":"h","s":["Demonstrations and strikes"]},{"k":"p","s":["Demonstrations and strikes often take place in major cities, particularly in transport hubs, including international and national train stations, and around the Schuman area (EU quarter) in Brussels."]},{"k":"p","s":["Most demonstrations are peaceful, but there is a risk of unrest or violence. There has also been violence following major sporting fixtures. Demonstrations by farmers can block major roads and delay traffic. Demonstrations in the Schuman area can affect access to the British Embassy and the British Consulate General."]},{"k":"p","s":["Strike action is an ongoing issue that can cause severe travel disruption across the country and affect international travel. Strike action may be announced at short notice and planned strike action may be extended at short notice. Strikes can coincide with demonstrations and protests."]},{"k":"p","s":["For regular updates on any disruption, check local news and follow advice given by your travel provider. If you are in areas where large gatherings are taking place, remain vigilant and move away quickly if there are signs of disorder. Avoid protests, expect delays on some major roads and follow the advice of the authorities."]},{"k":"p","s":["For information on travel in Belgium, visit:"]},{"k":"li","s":[["Belgian Railways","https://www.belgiantrain.be/en"]," (train and metro travel)"]},{"k":"li","s":[["Brussels","https://www.stib-mivb.be/index.htm?l=en"],", ",["Walloon","https://www.letec.be/"]," and ",["Flemish","https://www.delijn.be/en/"]," (regional public transport)"]},{"k":"li","s":[["HERE map","https://wego.here.com/?map=50.84439,4.35607,16,omv"]]},{"k":"li","s":[["Brussels-Capital Region Transport and Mobility News","https://be.brussels/en/transport-mobility"]]},{"k":"p","s":["For international travel, visit:"]},{"k":"li","s":[["Brussels Airport Zaventem","https://www.brusselsairport.be/en/passengers"]]},{"k":"li","s":[["Charleroi Airport","https://www.brussels-charleroi-airport.com/"]]},{"k":"li","s":[["Antwerp Airport","https://www.antwerp-airport.com/"]]},{"k":"hs","s":["Security awareness"]},{"k":"p","s":["In the event of a security incident or any emergency, or if police carry out security operations at short notice, follow the instructions of the Belgian authorities."]},{"k":"p","s":["You can:"]},{"k":"li","s":["find information on the ",["Belgian Crisis Centre website","https://crisiscenter.be/en/what-can-you-do/stay-informed/official-information-channels"]]},{"k":"li","s":["follow the Crisis Centre accounts on ",["X","https://x.com/CrisiscenterBE"]," or ",["Facebook","https://www.facebook.com/CrisiscenterBE"]," to follow official information in the event of a major national incident"]},{"k":"li","s":["sign up to ",["BE-Alert","https://www.be-alert.be/en"]," to receive emergency alerts on SMS"]},{"k":"li","s":["look for the official communication and social media channels of local police for the area you are in"]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Theft and pickpocketing are common in crowded areas. Take care of your baggage and passports and beware of any attempts to distract you."]},{"k":"p","s":["Take extra care in major railway stations and on public transport, particularly at night. Thieves, pickpockets and muggers operate in busy areas, and there have been cases of violent robbery. Be aware of your surroundings particularly:"]},{"k":"li","s":["at Brussels Gare du Midi/Zuidstation (Eurostar terminal) and Brussels Gare du Nord"]},{"k":"li","s":["on international trains, mainly Paris-Brussels and Amsterdam-Brussels"]},{"k":"li","s":["in busy areas of central Brussels, including Schuman (the EU quarter)"]},{"k":"p","s":["Never leave luggage unattended. Luggage has been stolen from the racks at the end of carriages in high-speed trains (TGV and Thalys), usually just before the doors close."]},{"k":"p","s":["Thieves, usually on motorbikes, can break a car window and snatch valuables from the front or back passenger seat when a vehicle is stationary at traffic lights. If you see anything suspicious, report it to ",["local police authorities","https://www.politie.be/5998/nl/contact"],"."]},{"k":"p","s":["Additionally, be aware that drug use may be seen openly in train and metro stations across Brussels."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Only use official, licensed taxis. Do not get into taxis that stop to offer rides."]},{"k":"hs","s":["Organised crime"]},{"k":"p","s":["There are regular incidents of violent crime among organised crime gangs involved in drug trafficking, particularly in Brussels, Antwerp and other large cities. Confrontations between rival gangs have led to violent incidents including shootings, stabbings, and use of homemade explosives. The risk mostly affects those involved in drug crime, but there is always the risk of being in the wrong place at the wrong time. Remain vigilant if you suspect illegal activity. Follow the advice of local authorities."]},{"k":"p","s":["There have been reports of truck and van drivers being approached at parking lots or service stations by organised crime groups and asked to smuggle products to the UK (‘window tapping’). If you see anything suspicious, report it to ",["local police authorities.","https://www.politie.be/5998/nl/contact"]]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You must carry your passport with you at all times."]},{"k":"hs","s":["Laws on clothing"]},{"k":"p","s":["It is illegal to wear clothing that hides your face partially or completely (for example, the burka and niqab) in public places. You risk a fine of up to 137 euros and detention for up to 7 days. There is no exemption for tourists."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Possession, use, or trafficking of illegal drugs, including cannabis, are serious offences and can lead to a minimum 3-month prison sentence, long jail terms, or heavy fines. You should expect severe penalties even when transiting through the airport."]},{"k":"p","s":["Airports in Belgium have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Visiting battlefields"]},{"k":"p","s":["When visiting WW1 battlefields in north-west Belgium, stay on the footpaths and be cautious if you see anything that looks like shells or munitions. Unexploded shells have recently been uncovered. Move away from the site and report incidents to the police."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Belgium, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],". Read the ",["government information on driving laws in Belgium","https://mobilit.belgium.be/nl/weg/rijden/wegcode-verkeersregels-en-sancties"]," (in Flemish and French)."]},{"k":"p","s":["When driving in Belgium, always carry:"]},{"k":"li","s":["your driving licence"]},{"k":"li","s":["your car registration documents"]},{"k":"li","s":["your insurance paper"]},{"k":"li","s":["your MOT (‘contrôle technique’) certificate"]},{"k":"li","s":["your passport and your passengers’ passports"]},{"k":"p","s":["If you are visiting Belgium, you may be able to use your ",["Blue Badge","https://www.gov.uk/government/publications/blue-badge-using-it-in-the-eu/using-a-blue-badge-in-the-european-union"]," in some circumstances. Check local parking rules."]},{"k":"p","s":["If you live in Belgium, see ",["driving requirements for residents","https://www.gov.uk/guidance/living-in-belgium#driving-in-belgium"],"."]},{"k":"hs","s":["Driving regulations"]},{"k":"p","s":["Driving laws differ from those in the UK. Be aware that:"]},{"k":"li","s":["police use speed traps, cameras and unmarked vehicles"]},{"k":"li","s":["speeding can result in an on-the-spot fine"]},{"k":"li","s":["using a mobile phone while driving is illegal, unless you are using hands-free equipment"]},{"k":"p","s":["Belgium’s accident rate is high, mainly due to speeding."]},{"k":"p","s":["If you get a fine, you can consult the ",["federal justice service","https://justonweb.be/fines/online-help"]," for information."]},{"k":"hs","s":["Low emission zones"]},{"k":"p","s":["There are low emission zones in Brussels, Ghent and Antwerp. You need to pre-register foreign vehicles on the ",["Brussels","https://lez.brussels/mytax/en/registration"],", ",["Ghent","https://stad.gent/en/mobility-ghent/low-emission-zone-ghent"]," or ",["Antwerp","https://www.slimnaarantwerpen.be/en/LEZ/registration/overview"]," websites."]},{"k":"hs","s":["Electric scooter regulations"]},{"k":"p","s":["The maximum speed limit for riding an electric scooter is 25kph and riding with a passenger is illegal. Riding a scooter on the pavement is prohibited with the exception of people with reduced mobility using a mobility scooter."]},{"k":"p","s":["It is illegal for people aged under 16 to use electric scooters, except in a few designated areas."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Belgium","https://travelhealthpro.org.uk/country/25/belgium#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Belgium","https://travelhealthpro.org.uk/country/25/belgium"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["For further information on the legal status of a specific medicine, contact the ",["Belgian Embassy in the UK","https://unitedkingdom.diplomatie.belgium.be/en"],"."]},{"k":"h","s":["Healthcare in Belgium"]},{"k":"p","s":["FCDO has a list of ",["medical providers in Belgium","https://www.gov.uk/government/publications/belgium-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"p","s":["There is a fee for non-emergency medical consultations and prescriptions. You may be able to recover this money through your travel insurance."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Belgium, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Belgium","https://www.gov.uk/guidance/healthcare-in-belgium"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Belgium"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"p","s":["Download the ",["112 BE app","https://112.be/en"],", the official Belgian emergency app for ambulance, fire and police services. This allows you to contact emergency services directly and helps responders identify your location and personal details."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Belgium"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Belgium"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Belgium"]," in Belgium"]},{"k":"li","s":["dealing with a ",["death in Belgium","https://www.gov.uk/government/publications/bereavement-information-pack-belgium"]]},{"k":"li","s":["being ",["arrested or imprisoned in Belgium","https://www.gov.uk/government/publications/belgium-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/belgium/british-embassy-brussels"]," including in a crisis."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/belgium/email-signup"]," when this travel advice is updated. when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Belgium","https://www.gov.uk/government/publications/overseas-business-risk-belgium"]," on how to manage political, economic, and business security-related risks."]}],"chars":20873,"change":"Additional information on demonstrations and strikes (Safety and security)."},"https://www.gov.uk/foreign-travel-advice/switzerland":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"d00bc9336ea2734c3e7bc618e62d3f08a471a18d5d385047aff3c4bd5b098f52","read":"https://www.gov.uk/api/content/foreign-travel-advice/switzerland","bytes":76422,"x":"fulltext v1","title":"Switzerland travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-21T00:00:00+00:00","mod":"2026-08-11T10:23:45+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["G7 Summit"]},{"k":"p","s":["The G7 Summit will be taking place in Evian, France, between 15-17 June 2026. A number of attendees will be transiting through Geneva."]},{"k":"p","s":["In preparation, the Swiss authorities are preparing to close several border crossings with France over the dates surrounding the Summit, which is likely to lead to severe delays at the crossings that remain open. You should plan your journey carefully and consider avoiding travel between France and Switzerland on these dates if possible."]},{"k":"p","s":["The Swiss authorities have given permission for a protest linked to the G7 in central Geneva on the afternoon of Sunday 14 June. There may be other unauthorised protest activity related to the G7 around the period from 12-19 June. Stay away from any areas where protest activity is underway and follow the instructions of the authorities."]},{"k":"p","s":["The ",["Republic and Canton of Geneva","https://www.ge.ch/dossier/sommet-du-g7-evian-2026"]," (in French) has further information on the Swiss preparations for the G7 Summit."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/switzerland/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Switzerland set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Swiss Embassy in the UK","https://www.eda.admin.ch/london"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Switzerland follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the day you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Switzerland, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["At passport control, use the ‘All passports’ lane."]},{"k":"p","s":["The ",["requirements for working in Switzerland","https://www.gov.uk/guidance/travel-to-switzerland-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Swiss border control, you may also need to:"]},{"k":"li","s":["show proof of your accommodation, for example, a hotel booking or proof of address if visiting your own property"]},{"k":"li","s":["show proof of insurance for your trip"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – around 100 Swiss francs a day"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, you must meet the Swiss government’s entry requirements. Check which type of visa or work permit you need with the ",["Swiss Embassy in the UK","https://www.eda.admin.ch/london"],"."]},{"k":"p","s":["If you are in Switzerland with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["See ",["entry processes if you live in Switzerland","https://www.gov.uk/guidance/living-in-switzerland#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["At least 8 weeks before your trip, check the vaccinations and certificates you need in ",["TravelHealthPro’s Switzerland guide","https://travelhealthpro.org.uk/country/216/switzerland#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods that you can take into and out of Switzerland","https://www.ch.ch/en/customs"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Switzerland"]},{"k":"p","s":["Terrorist attacks in Switzerland cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"p","s":["There is a low rate of serious crime in Switzerland. However, there have been increased reports of petty theft, especially in larger cities, at Geneva airport and on trains to and from Geneva."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Take sensible precautions to avoid mugging, bag-snatching and pickpocketing. Be particularly alert at airports, railway stations and in crowded areas. Do not leave your valuables unattended."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, carry severe penalties. You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Switzerland have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Face-covering ban"]},{"k":"p","s":["In Ticino and St Gallen, it’s illegal to cover your face in public, including for tourists. Do not wear balaclavas, full veils or any other garment or mask that hides your face. You could get a fine of 100 to 10,000 Swiss francs if you do not comply."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Hiking, mountaineering and extreme sports"]},{"k":"p","s":["Adventure sports can be risky. British nationals in the Swiss Alps have been involved in accidents and have been hospitalised or died."]},{"k":"p","s":["Check the company you are using is well-established and that your travel insurance covers any specific activity."]},{"k":"p","s":["For sports activities like skiing, potholing and mountaineering, and for sports classed as particularly dangerous (for example, off-piste skiing, mountain biking, climbing, paragliding or BASE jumping), you could get into difficulty and need emergency rescue. Your insurance should include:"]},{"k":"li","s":["mountain rescue services"]},{"k":"li","s":["helicopter costs"]},{"k":"li","s":["repatriation to your home country or transfer to neighbouring countries for treatment"]},{"k":"p","s":["See ‘Altitude sickness’ in ",["Health","https://www.gov.uk/foreign-travel-advice/switzerland/health#health-risks"],"."]},{"k":"hs","s":["Skiing and winter sports"]},{"k":"p","s":["Read FCDO advice about ",["preparing for winter sports abroad","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],". See the guidance on avalanches in ‘Extreme weather’."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Switzerland, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and read the ",["rules of the road in the RAC’s Switzerland guide","https://www.rac.co.uk/drive/travel/country/switzerland/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["Road users must observe ",["Switzerland’s traffic laws","https://www.ch.ch/en/how-behave-road-traffic/"],", including speed limits, rules on alcohol intake and child security. Traffic police strictly enforce these regulations. Any serious breach can result in heavy fines or imprisonment."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Switzerland. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If you are visiting Switzerland, you may be able to use your ",["Blue Badge","https://www.gov.uk/government/publications/blue-badge-using-it-in-the-eu/using-a-blue-badge-in-the-european-union"]," in some circumstances. Check local parking rules."]},{"k":"hs","s":["Tolls"]},{"k":"p","s":["You must buy and display a vignette (sticker) to travel on Swiss motorways. You can buy one at most border crossings, petrol stations, post offices, by phone (+800 1002 0030) or ",["buy a vignette online","https://via.admin.ch/shop/dashboard"],". If you do not have a vignette, you could get a large fine."]},{"k":"p","s":["If you’re involved in a car accident, use the orange emergency phones to ask for help."]},{"k":"hs","s":["Road conditions"]},{"k":"p","s":["Roads outside urban areas are narrow and winding. Road conditions can deteriorate fast, even in summer, especially during heavy rainfall and snowfall at higher altitudes. Reduce your speed significantly to suit the conditions."]},{"k":"p","s":["Alpine winters make driving difficult. Equip your car with winter tyres and snow-chains. Check road conditions before you depart. Carry water, food, warm clothing and medicines in your vehicle."]},{"k":"p","s":["Find the latest information on road conditions using the ",["Swiss government’s ‘Easy answers’ website","https://www.ch.ch/en/travel-and-emigrate/useful-travel-information/#car-travel-traffic-information"],"."]},{"k":"hs","s":["Accessibility"]},{"k":"p","s":["The official Switzerland Tourism website has useful ",["information for travellers in wheelchairs or with impaired mobility","https://www.myswitzerland.com/en-ch/planning/transport-accommodation/barrier-free-travel/"]," who are travelling in Switzerland."]},{"k":"h","s":["Extreme weather and natural hazards"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Alpine conditions"]},{"k":"p","s":["Check weather forecasts and conditions and make sure you’re properly equipped for the worst-case scenario. Always carry a map, compass, GPS and fully charged mobile when travelling outside urban areas. Do not undertake any activity alone and consider hiring a guide for expert advice. Always leave copies of your itinerary with someone."]},{"k":"p","s":["These alpine hazards exist throughout the year:"]},{"k":"li","s":["avalanches and snowdrifts"]},{"k":"li","s":["landslides and flooding"]},{"k":"li","s":["glacial crevasses and hollows"]},{"k":"li","s":["rockfalls"]},{"k":"li","s":["thunderstorms"]},{"k":"li","s":["altitude sickness"]},{"k":"li","s":["sun exposure"]},{"k":"li","s":["sudden weather changes"]},{"k":"hs","s":["Avalanches"]},{"k":"p","s":["Avalanches are a risk, particularly during heavy snow. Off-piste skiing is very dangerous due to the risk of avalanches. Follow safety instructions and warnings. Consider carrying search equipment. Avalanche beepers (receivers) are the most common rescue devices and when properly used, are the fastest way of locating an avalanche victim."]},{"k":"p","s":["Conditions on roads in mountainous areas can quickly become difficult in winter. Carry water, food, warm clothing and medicines in your vehicle."]},{"k":"p","s":["Check the latest avalanche risk at the Federal Office of Meteorology and Climatology."]},{"k":"p","s":["For more information, visit the ",["official Switzerland Tourism website","https://www.myswitzerland.com/en-gb/home.html"],"."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["There is a heightened risk of wildfires in summer, especially after a period of drought."]},{"k":"p","s":["Fires in mountainous areas can lead to rockfalls. Wildfires also cause travel disruption in wider areas."]},{"k":"p","s":["Always check the ",["bans on open fires for the area you’re visiting","https://www.waldbrandgefahr.ch/en/current-measures"]," and:"]},{"k":"li","s":["leave no litter"]},{"k":"li","s":["make sure cigarette ends are properly extinguished"]},{"k":"li","s":["use only designated concrete-based barbecue areas and douse coals before you leave"]},{"k":"p","s":["Causing a forest fire in a place where there’s a ban is illegal, even if unintentional, and can lead to a fine of up to 20,000 Swiss francs."]},{"k":"p","s":["If you see a wildfire, call the fire department on 118."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 or 144 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Switzerland","https://travelhealthpro.org.uk/country/216/switzerland#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Switzerland","https://travelhealthpro.org.uk/country/216/switzerland"],", including:"]},{"k":"li","s":["biting insects and ticks, especially between April and October"]},{"k":"li","s":["tick-borne encephalitis"]},{"k":"hs","s":["Altitude sickness"]},{"k":"p","s":["Altitude sickness is a risk in parts of Switzerland, including the ski and hiking areas around:"]},{"k":"li","s":["4 Vallées"]},{"k":"li","s":["Belalp-Blatten"]},{"k":"li","s":["Chandolin"]},{"k":"li","s":["Corvatsch"]},{"k":"li","s":["Engelberg-Titlis"]},{"k":"li","s":["Hohensaas"]},{"k":"li","s":["Lauchernalp"]},{"k":"li","s":["Matterhorn"]},{"k":"li","s":["Saas-Fee"]},{"k":"li","s":["St Moritz"]},{"k":"p","s":["Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Switzerland"]},{"k":"p","s":["FCDO has a list of ",["medical providers in Switzerland","https://www.gov.uk/government/publications/switzerland-and-liechtenstein-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Switzerland, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Switzerland","https://www.gov.uk/guidance/healthcare-in-switzerland"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Switzerland"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"p","s":["Ambulance: 144"]},{"k":"p","s":["Fire: 118"]},{"k":"p","s":["Police: 117"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Switzerland"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Switzerland"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Switzerland"]," in Switzerland"]},{"k":"li","s":["dealing with a ",["death in Switzerland","https://www.gov.uk/government/publications/bereavement-guide-for-switzerland-and-liechtenstein"]]},{"k":"li","s":["being ",["arrested in Switzerland","https://www.gov.uk/government/publications/switzerland-prisoner-pack/information-pack-for-british-nationals-detained-or-imprisoned-in-switzerland"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/switzerland/british-embassy-berne"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/switzerland/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Switzerland","https://www.gov.uk/government/publications/overseas-business-risk-switzerland"]," on how to manage political, economic, and business security-related risks."]}],"chars":17955,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."},"https://theconversation.com/georgia-gov-elect-keisha-lance-bottoms-stands-on-the-shoulders-of-stacey-abrams-charlotta-bass-and-countless-other-black-women-who-dreamed-296027":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"e38ff1b707aff68d2a71c93b2f53c0c0200c0befce8bf4517b3c5a9c461fac6a","read":"https://theconversation.com/georgia-gov-elect-keisha-lance-bottoms-stands-on-the-shoulders-of-stacey-abrams-charlotta-bass-and-countless-other-black-women-who-dreamed-296027","bytes":186487,"x":"fulltext v1","title":"Georgia Gov.-elect Keisha Lance Bottoms stands on the shoulders of Stacey Abrams, Charlotta Bass and countless other Black women who dreamed","by":[{"n":"Allissa V. Richardson","r":"Associate Professor of Journalism, USC Annenberg School for Communication and Journalism"}],"pub":"2026-11-06T17:09:28Z","mod":"","blocks":[{"k":"p","s":["There are elections that change the political map. And then there are elections that make you wonder whether the land itself remembers."]},{"k":"p","s":["Georgia remembers."]},{"k":"p","s":[["The auction blocks","https://www.smithsonianmag.com/smart-news/horrors-great-slave-auction-180962287/"],". ",["The cotton fields","https://www.georgiaencyclopedia.org/articles/history-archaeology/slavery-in-antebellum-georgia/"],". ",["The lynching trees","https://www.georgiaencyclopedia.org/articles/history-archaeology/lynching/"],". The Black women who cleaned governors’ homes but could not dream of becoming governor themselves."]},{"k":"p","s":["And now Keisha Lance Bottoms has been elected ",["Georgia’s first Black woman governor","https://apnews.com/article/georgia-governor-lance-bottom-jackson-midterm-election-67c22a38b9a6e4cad5584aa44acf106f"],". The first Black woman elected governor of any American state."]},{"k":"p","s":["Bottoms has ",["traced her ancestry back five generations","https://www.ajc.com/politics/2026/11/keisha-lance-bottoms-crawfordville-governors-mansion/"]," to an enslaved person on a plantation near Crawfordville, Georgia."]},{"k":"p","s":["An ancestor held in bondage on Georgia soil. A descendant elected to govern it."]},{"k":"p","s":["The same earth. An entirely different claim to power. How many women had to believe in a future they would never live to see?"]},{"k":"p","s":["Bottoms’s victory represents the paradox of Black political advancement amid racial violence and the often-unrecognized labor of women who build futures they may never inhabit. Ultimately, Bottoms’ victory reflects both extraordinary progress and the unfinished work of American democracy."]},{"k":"h","s":["The children who deserved a future"]},{"k":"p","s":["I keep thinking about the little children."]},{"k":"p","s":["Between 1979 and 1981, ",["Atlanta was terrorized","https://www.nytimes.com/2019/04/30/us/atlanta-child-murders.html"]," by the disappearances and murders of Black children and young adults. Mothers pleaded for answers. Families lived in a city where childhood itself had become dangerous."]},{"k":"p","s":["The murders unfolded just years after ",["Maynard Jackson’s historic 1973 election","https://www.nytimes.com/1973/10/17/archives/atlanta-elects-a-black-mayor-first-in-a-major-southern-city-black.html"]," as Atlanta’s first Black mayor. His victory announced a new era of Black political power. Yet that power could not shield the city’s most vulnerable children. ",["Suspicions of Ku Klux Klan involvement circulated","https://www.washingtonpost.com/archive/politics/2005/08/07/klan-was-probed-in-child-killings-in-atlanta/334ee8d7-5322-428a-9ebe-d05efaacf19b/"],", although the Klan’s responsibility was never established."]},{"k":"p","s":["That distinction matters. So does the fear."]},{"k":"p","s":[["Bottoms was born in 1970","https://blackpast.org/african-american-history/keisha-lance-bottoms-1970/"],". She was 9 when the murders began. She grew up in the same Atlanta where Black parents searched desperately for their missing children. She belonged to the generation whose futures were being stolen. And now she is preparing to lead the entire state."]},{"k":"p","s":["What a terrible, beautiful, complicated thing."]},{"k":"p","s":["Those murdered children were not symbols waiting to become useful to history. They were sons and daughters who deserved the ordinary miracle of growing older. They deserved a future."]},{"k":"p","s":[["Bottoms later occupied the mayor’s office","https://nul.org/basic-page/state-black-america-mayor-keisha-lance-bottoms"]," that Jackson first opened to Black leadership. Now she is preparing to occupy the governor’s mansion. History has not erased its cruelty. But it has delivered an astonishing answer."]},{"k":"p","s":["And this victory does not belong to Bottoms alone."]},{"k":"h","s":["The woman who sowed the seeds"]},{"k":"p","s":["This victory belongs, in no small measure, to ",["democracy advocate, legislator and lawyer Stacey Abrams","https://civilrightsmuseum.org/blog/stacey-abrams-champion-of-voting-rights-honored-at-the-national-civil-rights-museum/"],". Perhaps those who recognize what Abrams made possible have sent her flowers."]},{"k":"p","s":["Abrams ran for Georgia governor in 2018 and 2022. She ",["lost both races","https://atlanta.capitalbnews.org/abrams-loss-recap/"],". But through the ",["New Georgia Project","https://slsvcoalition.org/partner/new-georgia-project/"]," and ",["Fair Fight","https://fairfight.com/"],", organizations focused on engaging voters and protecting voting rights, she helped build an electorate that could imagine Georgia differently. ",["She registered voters, challenged barriers to participation","https://www.britannica.com/question/How-has-Stacey-Abrams-worked-to-protect-voting-rights"],", and refused to accept that the South’s political future was fixed."]},{"k":"p","s":["And now another Black woman has won the office Abrams twice sought, in the third gubernatorial race in a row ",["headed by a Black Democratic woman","https://amsterdamnews.com/news/2026/11/03/keisha-lance-bottoms-wins-georgia-governor/"],". There is something biblical about the path Abrams steadfastly cleared. I think of Moses, guiding his people toward the Promised Land but never entering it himself."]},{"k":"p","s":["Abrams’ journey is not over. Nor should her accomplishments be measured by another woman’s victory. But I believe there is sacred work in preparing a future you may never personally enjoy. Some people plant trees. Some people sit in their shade. Stacey Abrams planted. Bottoms is standing beneath the branches."]},{"k":"p","s":["And as ",["a scholar of Black media history","https://annenberg.usc.edu/faculty/allissa-v-richardson"],", I can reach even further back, to another woman who understood the audacity of claiming political power: ",["Charlotta Bass","https://scetv.pbslearningmedia.org/resource/ull20-charlotta-spears-bass-video/unladylike2020/"],"."]},{"k":"p","s":["In 1952, Bass became ",["the first Black woman nominated for vice president","https://www.womenshistory.org/education-resources/biographies/charlotta-spears-bass"]," of the United States, running on the Progressive Party ticket."]},{"k":"h","s":["The future Charlotta dared to imagine"]},{"k":"p","s":["Before the ",["Voting Rights Act","https://www.archives.gov/milestone-documents/voting-rights-act"]," in 1965, before ",["the March on Washington","https://naacp.org/find-resources/history-explained/1963-march-washington"]," in 1963, before ",["Jackson was elected mayor","https://www.nps.gov/features/malu/feat0002/wof/Maynard_Jackson.htm"]," in 1973 and before Abrams or Bottoms drew their first breaths, there was Bass."]},{"k":"p","s":["A Black newspaper publisher who ",["confronted segregation, police brutality and white supremacist violence","https://pdf.core.ac.uk/corefilesystem/pdf/3479/232565552.pdf?se=2026-11-06T14%3A49%3A25Z&sp=r&sv=2026-10-06&sr=b&rscd=inline%3B%20filename%3D%22232565552.pdf%22&rsct=application/pdf&sig=Y7M28jTj/2PaKi3HGTqRECrtsAL1wcvmVpZVSCC87xI%3D"]," in her four-decade ownership of ",["The California Eagle","https://www.pbs.org/blackpress/news_bios/ca_eagle.html"],", Bass understood that political power was about more than winning office. It was about who had the right to imagine themselves in one."]},{"k":"p","s":["Bass ran when ",["a Black woman entering the White House","https://www.cnn.com/2020/08/14/us/charlotta-bass-kamala-harris-trnd"]," seemed almost unimaginable. Almost. But not to her. I imagine she would have loved this election. And I suspect she would have had pointed questions for Gov.-elect Bottoms."]},{"k":"p","s":["What will you do for the poor? The disenfranchised? How will you protect the vote that brought you here?"]},{"k":"p","s":["History-making is not the same as justice-making, and representation matters. The true measure of Bottoms’ victory will be whether Georgians experience the more just state ",["she promised to bring about","https://www.wrdw.com/2026/11/03/billionaire-rick-jackson-atlanta-ex-mayor-keisha-lance-bottoms-vie-lead-georgia/"],"."]},{"k":"h","s":["The work beyond the win"]},{"k":"p","s":["For generations, ",["Black women have been asked to save a democracy","https://www.basicbooks.com/titles/martha-s-jones/vanguard/9781541618619/"]," that would not save them. We have carried clipboards, protest signs and entire movements on our backs. We have been told to wait. To be patient. To be grateful."]},{"k":"p","s":["And now a Black woman has been elected to govern Georgia."]},{"k":"p","s":["The children have not returned. The past has not been undone. But something has shifted. Charlotta dreamed it. Stacey helped build it. Keisha has won it. And somewhere, another little Black girl is watching. She may not understand the history. She may only know that the governor-elect looks like her. For now, that is enough to begin a dream."]},{"k":"p","s":["And history has taught us what can happen when a Black girl begins to dream."]}],"chars":5805},"https://www.gov.uk/foreign-travel-advice/equatorial-guinea":{"r":"govuk","at":"2026-11-17T16:38Z","sha":"5c8c124b748ed37e341dfb8da5f48d9d9e22d7c4db2b03a1726cbb898fb200e3","read":"https://www.gov.uk/api/content/foreign-travel-advice/equatorial-guinea","bytes":45357,"x":"fulltext v1","title":"Equatorial Guinea travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-10T00:00:00+00:00","mod":"2026-01-08T10:25:07+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/equatorial-guinea/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Equatorial Guinea’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Equatorial Guinea set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Equatorial Guinea Embassy in the UK:"]},{"k":"p","s":["Telephone: +44 7918 289 393"]},{"k":"p","s":["Email: info@embareage-londres.uk"]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Equatorial Guinea, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Equatorial Guinea. Short-term visas are valid for 90 days. For longer stays you must apply at local police stations."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["Complete the ",["online visa application form","https://equatorialguinea-evisa.com/"]," and upload the required documents. The processing time is 72 hours. Print out the e-visa letter to present on arrival, and border officials will issue your visa."]},{"k":"p","s":["You can also apply in person at the embassy and get the visa before you travel."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure the border control officer issues your visa and puts a stamp in your passport. Travellers have reported being delayed or threatened with detention because their passports have not been properly processed."]},{"k":"hs","s":["Residence permits"]},{"k":"p","s":["Long-term visitors must get a residence permit of one-year validity from the Ministry of National Security. If you have a residence permit, you will not need a visa."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["You must have a certificate to prove you’ve had a yellow fever vaccination, due to a risk of yellow fever transmission."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, including yellow fever, see ",["TravelHealthPro’s Equatorial Guinea guide","https://www.travelhealthpro.org.uk/country/73/equatorial-guinea#Vaccine_Recommendations"],"."]},{"k":"h","s":["Health screening"]},{"k":"p","s":["You may have to fill in a health questionnaire about any recent travel to Ebola-affected countries, including Liberia, Guinea and Sierra Leone."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Equatorial Guinea"]},{"k":"p","s":["Although there’s no recent history of terrorism in Equatorial Guinea, attacks cannot be ruled out."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["The political situation has been calm in recent years, but police, military or security forces respond swiftly to any political protests on the streets. Avoid any political rallies, demonstrations or large public gatherings."]},{"k":"h","s":["Commercial disputes"]},{"k":"p","s":["The authorities can stop you from leaving the country if you’re involved in a commercial dispute. There have been occasions when expatriate staff of foreign companies have been detained or confined to the country for prolonged periods. If you are detained, you could face months or years of imprisonment. Legal processes can be lengthy and complex."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Crimes range from petty theft and mugging to carjacking and armed robbery, risks can be greater in remote areas of towns, particularly after dark including around Malabo and Bata. You can reduce your personal risk by:"]},{"k":"li","s":["staying alert in public places"]},{"k":"li","s":["not wearing expensive-looking jewellery or watches"]},{"k":"li","s":["not travelling by road after dark"]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["There have been reports of robberies and violent assaults on passengers travelling by taxi in Malabo and Bata, particularly at night. You should:"]},{"k":"li","s":["use pre-booked taxis or taxi apps"]},{"k":"li","s":["ask your hotel or travel operator to arrange taxis"]},{"k":"li","s":["avoid taking taxis with groups or strangers"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry your passport or residence permit (or copies) with you throughout the country. Security checks have increased across the country. Follow all official advice and remain non-confrontational if stopped by authorities. If you fail to show identification documents on request, you could be arrested and detained."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Possession of drugs is a serious offence and punishments can be severe, including prison sentences."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["Photographing government or military buildings or airports is illegal and you could be arrested and detained."]},{"k":"hs","s":["Behaviour in public"]},{"k":"p","s":["Showing affection in public may attract unwanted and negative attention. It is uncommon for opposite or same-sex couples to show affection in public."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex relationships are not illegal in Equatorial Guinea, but there is no legal protection against discrimination based on sexual orientation. Society is very conservative and discrimination can be a problem for those open about their sexual identity. Same-sex marriage is not recognised in Equatorial Guinea."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Money"]},{"k":"p","s":["You can only pay by credit card at a few major hotels including the Hilton and Sofitel. There are a limited number of ATMs in Malabo and Bata – some accept international bank cards. Local banks will exchange cash euros, British pounds and US dollars."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Equatorial Guinea, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["Most major roads on Bioko Island and the Rio Muni mainland are now paved. In some isolated rural areas the condition of the roads is likely to be poor."]},{"k":"p","s":["Public transport facilities, particularly on the mainland, are extremely limited."]},{"k":"p","s":["Drink-driving is a serious offence in Equatorial Guinea."]},{"k":"hs","s":["Roadblocks"]},{"k":"p","s":["Police and military roadblocks are common. You may be asked to show your passport or vehicle registration documents and explain your reason for being in the area. Failure to comply can lead to detention."]},{"k":"p","s":["There are regular reports of police and uniformed security forces at roadblocks asking for bribes. If this happens, you can ask for a ticket, detailing alleged offences or violations, which you can pay at a local court."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["The ",["UK Air Safety List","https://www.gov.uk/guidance/uk-air-safety-list"]," (ASL) lists all known airlines in Equatorial Guinea that do not meet international safety standards and are banned from operating commercial air services to, from, and within the UK. Check the UK Air Safety List when considering which airlines to fly with. The list is maintained by the Department for Transport, based on advice from the ",["UK Civil Aviation Authority","https://www.caa.co.uk/Commercial-Industry/Airlines/Licensing/Requirements-and-guidance/Third-Country-Operator-Certificates"],"."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["There have been armed attacks on commercial shipping vessels in the Gulf of Guinea. Take extreme care when sailing in coastal waters."]},{"k":"p","s":["If you’re travelling by sea, ",["read about the regional risks at sea","https://www.gov.uk/guidance/sea-river-and-piracy-safety"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 3101 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Equatorial Guinea","https://travelhealthpro.org.uk/country/73/equatorial-guinea#Vaccine_recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Equatorial Guinea","https://travelhealthpro.org.uk/country/73/equatorial-guinea"]," including:"]},{"k":"li","s":["malaria and dengue"]},{"k":"li","s":["Schistosomiasis"]},{"k":"li","s":["Zika virus"]},{"k":"p","s":["Altitude sickness is a risk in parts of Equatorial Guinea. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["Marburg virus disease (MVD)"]},{"k":"p","s":["In June 2023, the outbreak of ",["Marburg virus disease","https://www.who.int/health-topics/marburg-virus-disease/#tab=tab_1"]," was declared over by the World Health Organisation (WHO) and the Equatorial Guinea government. No new cases have been reported."]},{"k":"p","s":["Check the latest situation with local authorities before travelling. You can find more information on Marburg virus disease from the ",["WHO","https://www.who.int/emergencies/disease-outbreak-news/item/2023-DON449"],", and ",["TravelHealthPro","https://travelhealthpro.org.uk/news/693/marburg-virus-disease-in-equatorial-guinea"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries. Pharmacies in Malabo and Bata stock basic medication."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Equatorial Guinea"]},{"k":"p","s":["Medical facilities are generally poor, apart from the La Paz hospital in Malabo. Emergency facilities are extremely limited. For serious medical treatment, evacuation to Europe is likely. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Equatorial Guinea"]},{"k":"p","s":["Ambulance: 3101"]},{"k":"p","s":["Police: 666 404040 or 666 303030"]},{"k":"p","s":["Emergency numbers and emergency response are unreliable. Emergency help can be limited in some places that are hard to reach. You may need to get local advice and arrange private transport."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["being ",["arrested or imprisoned in Equatorial Guinea","https://www.gov.uk/government/publications/equatorial-guinea-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/equatorial-guinea/british-high-commission-yaounde"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/equatorial-guinea/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":11868,"change":"Updated information on commercial disputes (‘Safety and security’ page)."},"https://theconversation.com/darurat-bencana-jadi-ruang-korupsi-akibat-4-celah-penyelewengan-ini-294508":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"52f1fa5cd05b1704025d2c8ba4082b6f234b036b95d36425c1b1db94801623d9","read":"https://theconversation.com/darurat-bencana-jadi-ruang-korupsi-akibat-4-celah-penyelewengan-ini-294508","bytes":188104,"x":"fulltext v1","title":"Darurat bencana jadi ruang korupsi akibat 4 celah penyelewengan ini","by":[{"n":"Rudi Syaf Putra","r":"Lecturer at Universitas Muhammadiyah Riau & PhD Candidate, Universiti Malaysia Terengganu"}],"pub":"2026-10-19T04:00:06Z","mod":"","blocks":[{"k":"p","s":["● KPK menelisik dugaan korupsi dana penanggulangan bencana karhutla BNPB."]},{"k":"p","s":["● Ibarat tradisi, setiap ada bencana besar nasional pasti ada yang korupsi."]},{"k":"p","s":["● Karena harus cepat dicairkan, dana bencana memiliki berbagai celah untuk dikorupsi."]},{"k":"p","s":["Anggaran negara yang memiliki perencanaan belanja yang ketat sebenarnya cukup fleksibel terhadap pencairan dana darurat, khususnya ketika menghadapi bencana seperti kebakaran hutan dan lahan (karhutla)."]},{"k":"p","s":["Karhutla yang sedang terjadi ",["sejak awal tahun ini","https://green.katadata.co.id/berita/6a951ce53f3c8/karhutla-2026-meluas-pakar-soroti-lemahnya-upaya-pencegahan"]," tercatat telah menghanguskan 677 ribu hektare hutan maupun lahan. Asap mengganggu ",["kesehatan jutaan warga hingga ke negara tetangga","https://fire.nusantara.earth/id"],"."]},{"k":"p","s":["Namun alih-alih digunakan untuk memadamkan api, dana darurat bencana justru memicu sangkaan korupsi."]},{"k":"p","s":["Komisi Pemberantasan Korupsi (KPK) justru melakukan operasi tangkap tangan (OTT) yang melibatkan ",["adik Kepala Badan Nasional Penanggulangan Bencana/BNPB","https://www.kompas.id/artikel/kpk-tetapkan-5-tersangka-ott-bnpb-salah-satunya-adik-kepala-bnpb"]," sebagai tersangka korupsi dana darurat bencana karhutla. ",["Suharyanto","https://www.cnnindonesia.com/nasional/20261015105837-32-1415596/kristomei-sianturi-resmi-jabat-kepala-bnpb-gantikan-suharyanto"]," pun akhirnya dicopot dari jabatannya, Jumat 17 Oktober 2026."]},{"k":"p","s":["KPK ",["membidik dugaan korupsi pengadaan barang dan jasa","https://www.kompas.id/artikel/kpk-tetapkan-5-tersangka-ott-bnpb-salah-satunya-adik-kepala-bnpb"]," yang berkaitan dengan Dana Siap Pakai (DSP) kebencanaan BNPB terkait dua klaster: dugaan konflik kepentingan dan suap yang ",["turut disangka","https://www.antaranews.com/berita/5786725/kpk-duga-korupsi-dana-siap-pakai-bnpb-telah-terjadi-sejak-2022"]," telah berlangsung sejak tahun 2022."]},{"k":"p","s":["Ini bukan kali pertama ada sejumlah pihak yang memanfaatkan kesempatan dalam kesempitan. Nyatanya, momen bencana kerap menjadi salah satu ajang pesta para koruptor untuk menyelewengkan duit masyarakat."]},{"k":"p","s":["Read more: ",["Mengapa penangkapan tersangka tak cukup membuat publik percaya pemberantasan korupsi?","https://theconversation.com/mengapa-penangkapan-tersangka-tak-cukup-membuat-publik-percaya-pemberantasan-korupsi-289237"]]},{"k":"h","s":["Uang pasti tersedia dan ditambah sesuai kebutuhan"]},{"k":"p","s":[["Bencana memang tak bisa direspons seperti biasa","https://www.researchgate.net/publication/395688006_MANAJEMEN_BENCANA"],". Waktu sangat krusial. Salah langkah sedikit, bisa memperburuk keadaan dalam hitungan jam. Barang tertentu mungkin langka, dan penundaan pembeliannya dapat memperburuk keadaan."]},{"k":"p","s":["Dalam menanggulangi darurat bencana, BNPB bisa menggunakan ",["dana siap pakai","https://jdih.bnpb.go.id/dokumen/Peraturan/perban-nomor-4-tahun-2020"],"."]},{"k":"p","s":[["Penanggulangan bencana oleh BNPB juga melibatkan lembaga lain","https://jdih.bnpb.go.id/dokumen/Peraturan/perban-nomor-1-tahun-2026"]," seperti Kementerian Kehutanan, Kementerian Lingkungan Hidup (terkait teknis alam), Kementerian Kesehatan (urusan teknis kesehatan), Kementerian Sosial (bantuan sosial), Kementerian Pekerjaan Umum (infrastruktur penunjang), hingga TNI dan kepolisian (keamanan)."]},{"k":"p","s":["Pun jika suatu bencana semakin parah, negara bisa menambah alokasi anggaran tanpa melalui proses revisi APBN di ",["DPR","https://www.youtube.com/shorts/rp6NB-QHeRQ"],". Kementerian Keuangan bisa “menyuntik” anggaran tambahan sesuai kebutuhan tim teknis di lapangan. BNPB sendiri pada awal bulan ini mengajukan tambahan DSP kepada Kementerian Keuangan sebesar ",["Rp5,67 triliun","https://www.kompas.id/artikel/pemerintah-siapkan-tambahan-anggaran-penanggulangan-bencana"],"."]},{"k":"p","s":["Untuk tahun ini, pemerintah telah mengganggarkan setidaknya ",["Rp53 - 60 triliun","https://www.liputan6.com/news/read/6251984/dana-darurat-bencana-2026-tembus-rp60-triliun-ini-penjelasan-pemerintah#google_vignette"]," anggaran penanggulangan bencana yang bersumber dari pos belanja yang bisa ditunda, dana abadi, dan opsi penambahan utang."]},{"k":"p","s":["Kemudahan akses dana siap pakai beserta penggunaannya dalam masa tanggap darurat diatur dalam ",["Peraturan Pemerintah Nomor 21 Tahun 2008","https://peraturan.bpk.go.id/Details/4833/pp-no-21-tahun-2008"]," dan ",["Peraturan Lembaga Kebijakan Pengadaan Barang/Jasa Pemerintah (LKPP) Nomor 6 Tahun 2024","https://peraturan.bpk.go.id/Details/314293/peraturan-lkpp-no-6-tahun-2024"],"."]},{"k":"p","s":["Read more: ",["Mengapa koruptor lebih suka transaksi pakai uang tunai ketimbang digital?","https://theconversation.com/mengapa-koruptor-lebih-suka-transaksi-pakai-uang-tunai-ketimbang-digital-271655"]]},{"k":"h","s":["Empat celah yang sering dimanfaatkan"]},{"k":"p","s":["Dalam ",["sudut pandang perspektif audit forensik","https://www.researchgate.net/publication/380314573_Public_procurement_corruption"]," risiko penyalahgunaan pengadaan darurat bisa dilihat sepanjang rantai transaksi, mulai dari identifikasi kebutuhan sampai penggunaan barang atau jasa."]},{"k":"p","s":["Ada setidaknya empat celah yang bisa dimanfaatkan untuk “bermain”. Keempatnya sulit dihindari karena dalam penanganan bencana, kecepatan adalah kebutuhan. Pengetatan pengawasan, bahkan audit di tengah jalan, bisa menghambat kebutuhan bantuan yang dibutuhkan segera."]},{"k":"p","s":["Pertama, terbukanya opsi ",["penunjukan langsung","https://e-journal.unair.ac.id/JD/article/view/14376"]," saat bencana menjadi pintu masuk konflik kepentingan antara pejabat, tenaga ahli, dan penyedia. Artinya suatu lembaga bisa memilih penyedia barang atau jasa tanpa melalui tender yang memakan waktu."]},{"k":"p","s":["Sayangnya, proses yang sah secara formal dalam penunjukan langsung belum tentu bebas dari konflik kepentingan dan butuh pembuktian mendalam."]},{"k":"p","s":["Kedua, ",["kewajaran harga","https://news.detik.com/berita/d-7650010/saksi-korupsi-truk-basarnas-akui-bikin-data-fiktif-untuk-penetapan-harga"]," menjadi ruang abu-abu ketika pengadaan mendesak dilakukan. Hal yang perlu diuji adalah dasar penetapan harga, kesesuaian spesifikasi, volume, waktu, lokasi, dan bukti pembanding yang tersedia."]},{"k":"p","s":["Read more: ",["74 kg emas kasus korupsi disita polisi, tapi negara belum tentu bisa merampasnya","https://theconversation.com/74-kg-emas-kasus-korupsi-disita-polisi-tapi-negara-belum-tentu-bisa-merampasnya-287439"]]},{"k":"p","s":["Ketiga, idealnya pengadaan pemerintah tercatat dan terdokumentasi mulai dari pesanan, kontrak jika dipersyaratkan, bukti pengiriman, berita acara penerimaan, tagihan, dan pembayaran harus membentuk jejak transaksi yang konsisten. Tapi dalam keadaan darurat, kerap ada pengecualian atas urutan ",["prosedur normal, alasan, dan otorisasinya","https://jdih.bnpb.go.id/dokumen/Peraturan/perban-nomor-1-tahun-2026"],"."]},{"k":"p","s":["Keempat, ",["pengawasan lembaga pengawas terkait","https://e-ppid.bpk.go.id/lhp/42"]," terhadap pemeriksaan dalam proses sebelum dana dibelanjakan kerap dilonggarkan."]},{"k":"p","s":["Modus serupa juga ditemukan KPK, yakni dengan memanfaatkan pengadaan alat pelindung diri (APD) pada masa pandemi COVID. ",["Dalam uraiannya","https://kpk.go.id/id/publikasi-data/penanganan-perkara/dugaan-tindak-pidana-korupsi-pengadaan-alat-pelindung-diri-apd-di-kementerian-kesehatan-dengan-sumber-dana-dari-dana-siap-pakai-dsp-bnpb-tahun-2020?openTab=1"],", KPK menemukan dugaan penggunaan tanggal mundur dalam penetapan pengadaan APD di Kementerian Kesehatan yang menggunakan DSP BNPB."]},{"k":"p","s":["KPK juga menguraikan dugaan pembayaran sebelum tersedia kontrak atau pesanan, penentuan harga satuan yang tidak didasarkan pada harga pasar. Selain itu, dokumen kontrak tak memuat rincian pekerjaan dan hak serta kewajiban para pihak secara memadai—sehingga memuluskan dana ghaib senilai ",["Rp319 miliar hanya dari pengadaan APD saja","https://kpk.go.id/id/publikasi-data/penanganan-perkara/dugaan-tindak-pidana-korupsi-pengadaan-alat-pelindung-diri-apd-di-kementerian-kesehatan-dengan-sumber-dana-dari-dana-siap-pakai-dsp-bnpb-tahun-2020?openTab=1"],"."]},{"k":"h","s":["Momen menutup mata rantai setan"]},{"k":"p","s":["Sebagai negara hukum, dugaan korupsi dana bencana BNPB 2026 harus diselesaikan melalui proses hukum berdasarkan bukti."]},{"k":"p","s":["Pada saat yang sama, perkara ini memberi kesempatan kita untuk mengevaluasi tata kelola pendanaan darurat tanpa menggeneralisasi kesalahan kepada seluruh lembaga atau program."]},{"k":"p","s":["Karena itu, ",["setiap penggunaan prosedur darurat","https://foresight.bpk.go.id/wp-content/uploads/2021/09/IHPS-II-2020.pdf"]," perlu memiliki dasar kebutuhan, alasan pemilihan penyedia, pertimbangan kewajaran harga, dan persetujuan yang dapat ditelusuri dengan baik oleh pengguna anggaran."]},{"k":"p","s":["Selanjutnya pemerintah bisa menerapkan pengawasan berbasis risiko untuk transaksi bernilai besar. Hubungan afiliasi, perubahan pesanan yang tidak lazim, harga yang menyimpang dari pembanding yang relevan, dan bukti penerimaan yang tidak lengkap dapat menjadi prioritas pemeriksaan."]},{"k":"p","s":["Terakhir, pertanggungjawaban pascapengadaan harus jelas. Setiap transaksi wajib punya penanggung jawab, tenggat dokumen, verifikasi hasil, dan prosedur tindak lanjut jika ada masalah. Saat memakai prosedur darurat, mekanisme pengecekan susulan harus ditentukan dan dimandatkan sejak awal."]},{"k":"p","s":["Read more: ",["Koruptor tak cukup hanya dipenjara, uang rakyat harus dikembalikan","https://theconversation.com/koruptor-tak-cukup-hanya-dipenjara-uang-rakyat-harus-dikembalikan-268567"]]},{"k":"p","s":["Sebab mau bagaimanapun, kecepatan tetap harus diikuti dengan akuntabilitas pengelolaan duit negara dengan baik agar tetap menghasilkan manfaat publik, bukan justru membuka ruang bagi penyalahgunaan kewenangan."]}],"chars":6648},"https://theconversation.com/should-soldiers-who-confess-to-atrocities-get-anonymity-in-journalism-the-dilemma-at-the-heart-of-naza-293653":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"d2db647119cab64ea4f42d6f10c230756366d272ac91df81a380c508111ba0ff","read":"https://theconversation.com/should-soldiers-who-confess-to-atrocities-get-anonymity-in-journalism-the-dilemma-at-the-heart-of-naza-293653","bytes":184959,"x":"fulltext v1","title":"Should soldiers who confess to atrocities get anonymity in journalism? The dilemma at the heart of NAZA","by":[{"n":"Shenaz Kermalli","r":"Journalism Instructor, Toronto Metropolitan University"}],"pub":"2026-10-28T17:26:45Z","mod":"","blocks":[{"k":"p","s":["“I’d hear the final moments of a person’s life.” The Israeli military insider pauses."]},{"k":"p","s":["He is composed and soft-spoken, seated on a darkened rooftop against the night sky. His face and voice are digitally altered — protected by anonymity."]},{"k":"p","s":["“What did you hear inside a home?” the journalist asks."]},{"k":"p","s":["“Sounds of normal life,” he responds. “A prayer, the TV, a baby, a husband and wife talking.”"]},{"k":"p","s":["By this point in the film, we’ve learned about the Night Location project, in which the Israel Defence Forces (IDF) hack into the phones of Palestinian civilians they suspect of being Hamas operatives. They’re easiest to target in their homes at night, the insider explains."]},{"k":"p","s":["“How could you bomb when you hear a baby inside?”"]},{"k":"p","s":["Another pause. “The goal is to destroy.”"]},{"k":"p","s":["This exchange is one of many in ",["NAZA, a new investigative documentary","https://www.imdb.com/title/tt44766123/?_ssoLoop=1"]," by Israeli journalists Yuval Abraham and Rachel Szor, two of the co-directors of ",["the Oscar-winning No Other Land","https://www.imdb.com/title/tt30953759/"],"."]},{"k":"p","s":["Produced by The Guardian and JW Films, the film features interviews with 24 anonymous Israeli intelligence officers and military personnel, filmed in Tel Aviv. They describe how artificial intelligence and automated surveillance were used as military tactics to shape the targeting of Palestinians in Gaza after Oct. 7, 2023."]},{"k":"p","s":["Its title, NAZA, comes from a Hebrew military acronym for nezek agavi, or “collateral damage.” The term is used as a euphemism for the number of civilians expected to be killed in a strike."]},{"k":"p","s":["After its world premiere at the 83rd Venice International Film Festival in September, NAZA won the Special Jury Prize and received a ",["record-breaking standing ovation","https://www.cbc.ca/news/entertainment/naza-25-minute-standing-ovation-venice-9.7340656"],". This month, it began screening at select Canadian venues like ",["Hot Docs in Toronto","https://boxoffice.hotdocs.ca/websales/pages/info.aspx?evtinfo=658890%7Ecf285ddd-dacb-4f18-89b8-1252c6dcffa6&epguid=a2104450-7e47-4369-a17d-c247570c3939&mdy=10/28/2026&"]," and the ",["Cinémathèque québécoise in Montréal","https://www.cinematheque.qc.ca/en/cinema/naza/"],"."]},{"k":"p","s":["The film provokes uncomfortable questions about accountability — and about journalism itself."]},{"k":"h","s":["Listening to perpetrators"]},{"k":"p","s":["NAZA has drawn criticism from the Israeli government, which has threatened to ",["revoke the filmmakers’ citizenship","https://cpj.org/2026/09/netanyahu-escalates-threats-against-naza-filmmakers-with-proposed-citizenship-law/"],". The Israeli military has also said the film ",["contains fundamental errors","https://jweekly.com/2026/10/02/in-its-first-detailed-response-to-naza-documentary-idf-claims-fundamental-errors/"],"."]},{"k":"p","s":["But a different critique has emerged from the other direction: from those who question the ethics of whose testimony the film chooses to centre and protect."]},{"k":"p","s":[["Nora Barrows-Friedman","https://electronicintifada.net/blogs/nora-barrows-friedman"],", an editor and author who has reported from Israel, is one of them. “I have a kind of general revulsion toward the genre of film that people refer to as ‘shooting and crying,’” ",["she said in an interview","https://www.youtube.com/watch?v=L39sCinIOf4"]," with ",["Palestine House of Freedom","https://www.daralhurriya.org/"],", an American-based non-profit that advocates for Palestinian freedom, equality and human rights."]},{"k":"p","s":["In Hebrew, this ",["genre is known as yorim ve'bochim","https://mondoweiss.net/2026/10/shooting-and-craving-on-naza-and-the-mediated-obscene/"],". It describes media, literature or public statements in which soldiers or citizens express remorse, moral conflict or grief over violence they took part in while continuing to carry it out or defend the system behind it."]},{"k":"p","s":["“These filmmakers are literally protecting the identities of these genocidal soldiers as though people committing genocide have a legitimate right to be protected from accountability,” Barrows-Friedman argues."]},{"k":"p","s":["Gur Tsabar, executive director of the ",["Movement Media Hub","https://movementmediahub.org/"],", a public-relations agency supporting social justice movements, expressed similar views. ",["In a Facebook post","https://www.facebook.com/gurtsabar/posts/im-skipping-naza-and-honestly-im-struggling-to-understand-why-im-supposed-to-giv/10175361770300514/"]," that drew more than 3,000 likes, he wrote that he was “skipping NAZA.”"]},{"k":"p","s":["His reasoning? The atrocities being described in the film are nothing new. Palestinian journalists, of whom ",["at least 203 have been killed by Israel","https://www.ifj.org/fr/salle-de-presse/nouvelles/detail/category/communiques-de-presse/article/palestine-at-least-203-journalists-and-media-workers-killed-in-gaza"],", have been documenting them since the start of the war."]},{"k":"p","s":["He also points to a double standard that many journalists have noticed in western coverage of Israel-Palestine: Palestinian victims of Israeli violence are challenged more than Israeli victims of Hamas attacks."]},{"k":"p","s":["My own research suggests the same pattern. ",["In a study I conducted of Canadian coverage in the three months after the Oct. 7 attack","https://j-source.ca/canadian-newsrooms-are-stifling-palestinian-perspectives/"],", for example, a producer at a mainstream Canadian news outlet told me that Palestinian sources and story ideas are often subjected to an added burden of proof that Israeli ones are not. In one case, the producer was told to fact-check a guest’s account of a family member killed in an Israeli airstrike."]},{"k":"p","s":["“I would need a death certificate and a family tree,” the producer said. “I’ve never been asked to fact-check a guest’s personal sensitive claims before.”"]},{"k":"h","s":["The importance of anonymity"]},{"k":"p","s":["These critiques raise difficult questions for journalists seeking to decolonize their own practices and to examine whose voices their reporting protects and amplifies. Chief among them: Is it ethically defensible to grant anonymity to sources describing their participation in acts that may violate international law?"]},{"k":"p","s":["NAZA’s filmmakers treat their interviewees as both confidential journalistic sources and as witnesses to potentially serious crimes. That dual role is not unusual for journalists exposing wrongdoing by a state. Insiders are often the only people who can describe how a system works from within, and they rarely speak without protection."]},{"k":"p","s":["Consider ",["Edward Snowden","https://www.pbs.org/wgbh/frontline/article/how-edward-snowden-leaked-thousands-of-nsa-documents/"],", the former contractor for the United States National Security Agency who leaked classified documents ",["exposing global surveillance programs","https://www.theguardian.com/world/2013/jun/23/edward-snowden-nsa-files-timeline"],". When The Guardian broke the story in 2013, Snowden was an unnamed insider source. This case illustrates the journalistic principle at work: anonymity and source protection in journalism can bring to light what otherwise would remain hidden forever."]},{"k":"p","s":["NAZA would not exist without the anonymity granted to its sources, and there is little doubt the film is having an impact. At the screening I attended, the audience sat in pin-drop silence as the credits rolled."]},{"k":"h","s":["What journalism owes"]},{"k":"p","s":["The ultimate goal of documenting atrocities in journalism is ",["accountability for war crimes","https://gijn.org/stories/the-power-of-documenting-war-crimes-and-how-to-do-it/"],", and that remains nowhere in sight."]},{"k":"p","s":["What is clear, however, is that ",["the film has significantly unsettled","https://www.haaretz.com/opinion/editorial/2026-09-14/ty-article-opinion/israelis-must-watch-naza-and-confront-the-reality-of-gaza/000001a0-9c4e-dfa9-ada3-de4e11fd0000"]," Israeli audiences. That includes liberal Zionists, many of whom continue to hold the Israeli military in high regard or reject the characterization of Israel’s devastation of Gaza as genocide."]},{"k":"p","s":["Read more: ",["How to decolonize journalism — Podcast","https://theconversation.com/how-to-decolonize-journalism-podcast-192467"]]},{"k":"p","s":["Ameer Fakhoury, an analyst at the Van Leer Jerusalem Institute, says ",["opinion polls indicate","https://www.middleeasteye.net/news/whats-behind-rise-palestinian-vote-israels-2026-election?utm_source=Middle+East+Eye&utm_campaign=713414b5d2-EMAIL_CAMPAIGN_2026_10_21_03_43_COPY_01&utm_medium=email&utm_term=0_e9fb079abb-97526e256f-291087010"]," that about 80 per cent of Jewish Israelis support the destruction being inflicted on Palestinians. They are arguably among those who most need to see NAZA."]},{"k":"p","s":["The absence of accountability, additionally, presents an ethical question of its own: What role, if any, do journalists bear in ensuring potentially criminal sources face justice?"]},{"k":"p","s":["As journalists, our job is not to prosecute sources. It is to gather and verify information, expose wrongdoing and bring it to public attention. The result is a record that can inform public debate and, potentially, legal proceedings."]},{"k":"p","s":["Is there tension, or moral discomfort, in that? Yes. But the truth is a necessary starting point, even when it comes from people who may never face consequences for what they admit to."]},{"k":"p","s":["Palestinian journalists told this story first, and many died telling it. NAZA does not replace their record. It corroborates it. And so the question shouldn’t be whether NAZA’s sources deserve anonymity. It’s whether, without it, we would ever have heard them confess at all."]}],"chars":7142},"https://www.gov.uk/foreign-travel-advice/nauru":{"r":"govuk","at":"2026-11-17T17:03Z","sha":"878f8db91d41f70e1784edc3192166366498eea2d24bf6dac451438d51919340","read":"https://www.gov.uk/api/content/foreign-travel-advice/nauru","bytes":34184,"x":"fulltext v1","title":"Nauru travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-14T00:00:00+00:00","mod":"2026-03-19T14:03:07+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Global travel impacts due to escalation in the Middle East"]},{"k":"p","s":["Escalation in the Middle East has caused widespread travel disruption, including airspace closures, delayed and cancelled flights."]},{"k":"p","s":["Your travel plans may be affected, even if your destination is not in the Middle East. Before you travel:"]},{"k":"li","s":["check travel advice for any countries or territories you are transiting through"]},{"k":"li","s":["check for the latest updates from your airline or tour operator"]},{"k":"li","s":["review your travel insurance policy for coverage"]},{"k":"li","s":["monitor local and international media for the latest information and sign up for travel advice email alerts"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/nauru/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Nauru’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Nauru set and enforce entry rules."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Nauru, your passport must have an ‘expiry date’ at least 3 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Nauru."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["For details on how to apply, see the Nauru government’s visa requirements."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Nauru guide","https://travelhealthpro.org.uk/country/158/nauru#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Nauru. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["There are controls on ",["taking plants or animals into Nauru","https://justice.gov.nr/quarantine-division/"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Nauru"]},{"k":"p","s":["Although there is no recent history of terrorism in Nauru, attacks cannot be ruled out."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Do not get involved with illegal drugs of any kind. There are severe penalties including custodial sentences for drug offences."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex relationships are legal, but Nauru society is conservative and same-sex partners showing affection in public may cause offence. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Money"]},{"k":"p","s":["There is only one ATM on the island – at the Menen Hotel – and it is often out of cash. Credit cards are not accepted. Take enough Australian dollars in cash to cover your trip."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Nauru, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["Check licence requirements with your rental car firm."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Tropical cyclones"]},{"k":"p","s":["During the rainy season from November to May, there’s a risk of strong winds, sea swells and tropical cyclones. Monitor regional and international weather updates from the ",["World Meteorological Organization","https://severeweather.wmo.int/"]," and the Fiji Meteorological Service and check local newspapers and radio."]},{"k":"hs","s":["Drought"]},{"k":"p","s":["Nauru suffers from periods of severe drought. The authorities may impose water restrictions during these periods."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 111 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Nauru","https://travelhealthpro.org.uk/country/158/nauru#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Nauru","https://travelhealthpro.org.uk/country/158/nauru"],", including:"]},{"k":"li","s":["typhoid"]},{"k":"li","s":["insect and tick bites"]},{"k":"p","s":["Visitors have been bitten by stray dogs. To reduce the risk:"]},{"k":"li","s":["stay alert, particularly on the beach"]},{"k":"li","s":["do not run if you’re approached by a dog"]},{"k":"p","s":["Seek medical attention immediately if you’re bitten by a dog."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Supplies of basic and prescription medicines are limited on Nauru, so bring enough to last your whole trip. If you bring prescription drugs with you to Nauru, make sure they’re in the original packaging and bring your UK prescription."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Nauru"]},{"k":"p","s":["Medical facilities in Nauru are very basic. You may need medical evacuation to Australia by air ambulance."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Nauru"]},{"k":"p","s":["Ambulance: 111"]},{"k":"p","s":["Fire: 112"]},{"k":"p","s":["Police: 110"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["being ",["arrested or imprisoned in Nauru","https://www.gov.uk/government/publications/nauru-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/nauru/british-high-commission-honiara"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/nauru/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":7833,"change":"Updated information about global travel impacts due to escalation in the Middle East (‘Warnings and insurance’ page)."},"https://theconversation.com/fighting-in-yemen-has-made-crossing-the-bab-el-mandeb-even-more-dangerous-jeopardizing-aid-and-refuge-for-millions-295106":{"r":"conversation","at":"2026-11-17T21:26Z","sha":"50b659ac4c7170ea503cf591e81cb10b31ee49dc9a835af6bb781c1e355a6f44","read":"https://theconversation.com/fighting-in-yemen-has-made-crossing-the-bab-el-mandeb-even-more-dangerous-jeopardizing-aid-and-refuge-for-millions-295106","bytes":188051,"x":"fulltext v1","title":"Fighting in Yemen has made crossing the Bab el-Mandeb even more dangerous – jeopardizing aid and refuge for millions","by":[{"n":"Lauren Carruth","r":"Associate Professor of International Service, American University School of International Service"},{"n":"Lahra Smith","r":"Associate Professor of Political Science, Georgetown University"}],"pub":"2026-11-17T19:48:54Z","mod":"","blocks":[{"k":"p","s":["In recent days, Iran-backed Houthi forces have ",["gained greater control","https://www.aljazeera.com/news/2026/11/16/houthis-edge-closer-to-aden-as-yemeni-forces-pull-out-of-bab-al-mandeb"]," of the Bab al-Mandeb Strait, a vital hub of trade, travel and migration between the Middle East and Africa."]},{"k":"p","s":["The partial closing of the ",["Strait of Hormuz","https://www.cnbc.com/2026/09/30/iran-war-strait-hormuz-gulf-oil-fuel.html"]," as part of the ",["war in Iran","https://www.reuters.com/world/iran/"]," – and escalating conflicts in ",["Yemen","https://www.nytimes.com/2026/10/02/world/middleeast/yemen-houthis-saudi-arabia-sanaa-taiz.html"],", ",["Ethiopia and Eritrea","https://apnews.com/article/ethiopia-tigray-eritrea-abiy-ahmed-nile-18294adeefc435193ab569ddb9aa3d60"]," – had already brought this narrow waterway into new global prominence. Control over the Bab el-Mandeb Strait remains critical to military operations and commodity markets throughout the region."]},{"k":"p","s":["However, the Bab el-Mandeb’s ",["strategic geopolitical","https://www.reuters.com/world/middle-east/why-is-bab-el-mandeb-strait-so-important-2026-09-10/"]," and ",["commercial shipping","https://www.latimes.com/world-nation/story/2026-09-27/new-flash-point-in-iran-war-narrow-strait-called-gate-of-tears"]," importance has largely overshadowed its role as a critical humanitarian corridor."]},{"k":"p","s":["Bab el-Mandeb means “gate of lamentation” or, more poetically, “gate of tears” in Arabic. It remains one of the ",["most dangerous migration passages","https://storyteller.iom.int/gallery/understanding-migration-along-eastern-route-through-djibouti"]," in the world. Last year, ",["more than 900 people died or went missing","https://mixedmigration.org/publications/mmr/2026/bab-el-mandeb-yemenis-flee-migrants-arrive/"]," trying to cross. In October 2026, a ",["boat capsized","https://news.un.org/en/story/2026/10/1168573"]," off the coast of Djibouti carrying nearly 300 people, many of whom were escaping violence and persecution."]},{"k":"p","s":["Meanwhile, ",["millions of people in Yemen","https://news.un.org/en/story/2026/10/1168706"]," and throughout the ",["Horn of Africa","https://reliefweb.int/report/somalia/eastern-africa-el-nino-status-and-humanitarian-impacts-september-2026"]," face destitution or death without access to lifesaving deliveries of humanitarian relief supplies shipped through the strait."]},{"k":"p","s":["Our years of research and forthcoming book “ ",["Refugees Without Refuge","https://iupress.org/9780253077745/refugees-without-refuge/"],"” demonstrate how the Bab el-Mandeb Strait is key to the lives of millions of people throughout the region seeking safety, opportunity and humanitarian assistance. Protecting the safe movement of people and goods through the strait is key to averting future tragedies."]},{"k":"h","s":["A corridor for travel, trade and escape"]},{"k":"p","s":["Located at the southern mouth of the Red Sea, between the arid coastlines of Eritrea, Djibouti and Yemen, the ",["Bab el-Mandeb Strait","https://www.straitstimes.com/world/middle-east/explainer-why-is-the-bab-el-mandeb-strait-so-important"]," connects the Indian Ocean to the Red Sea and Suez Canal. On a clear day along the wide beaches and mangrove forests on the coast of Djibouti, you can see the sandy hills on the shores of Yemen, only about 20 to 30 miles away. On starry nights, the scattered lights of coastal towns twinkle across the waters."]},{"k":"p","s":["For centuries, passage through the Bab el-Mandeb Strait has been vital to ",["global trade in salt, spices, coffee, livestock","https://academic.oup.com/cairo-scholarship-online/book/18498"]," and other goods. Religious ",["pilgrims, travelers, migrants and traders","https://www.bloomsbury.com/us/life-of-the-red-sea-dhow-9781786734877/"]," have long used the strait for relatively easy transport between continents."]},{"k":"p","s":["Today, people crossing the strait are also escaping ",["poverty, war, political persecution, disasters","https://www.thenewhumanitarian.org/news-feature/2025/04/23/ethiopia-frustrated-youth-south-south-migration-africa"]," and ",["gender-based violence","https://www.cambridge.org/core/journals/journal-of-modern-african-studies/article/building-ones-own-house-power-and-escape-for-ethiopian-women-through-international-migration/69BC32D1B25D029D04046955A316AEA6"],"."]},{"k":"p","s":["Hot, tired, financially depleted and frequently sick or injured, refugees and migrants traverse the Bab el-Mandeb at all hours."]},{"k":"p","s":["Most negotiate passage across the strait on derelict boats with “delalas” – facilitators, brokers or smugglers – in the shadows of coast guard and police patrols and outside United Nations and governmental migration controls."]},{"k":"p","s":["The numbers of people crossing the strait are difficult to estimate. Between January and August 2026, the U.N.’s International Organization for Migration recorded ",["122,258 arrivals","https://dtm.iom.int/reports/yemen-flow-monitoring-registry-dashboard-incoming-and-outgoing-migrants-august-2026?close=true"]," to Yemen from the Horn of Africa – even more than had crossed by that time in 2025. Most of these migrants were from Ethiopia, and most traveled without passports or visas."]},{"k":"p","s":["Since August, displacement and insecurity throughout the region has worsened, making accurate figures for the numbers of people migrating and the numbers of people dying trying to cross impossible to estimate."]},{"k":"h","s":["A lifeline for those escaping conflict"]},{"k":"p","s":["Despite the dangers of this crossing, the Bab el-Mandeb Strait remains an economic lifeline for millions of people living in Ethiopia, Kenya, Somaliland, Somalia and elsewhere who rely on commercial goods imported from the Middle East and Asia. However, the ",["Houthi forces in charge of increasing swaths of southwestern Yemen","https://www.npr.org/2026/09/22/g-s1-144261/yemen-houthis-saudi-iran-humanitarian-crisis"]," now control most critical ports and islands in the strait, increasing the risks and costs of transit and trade."]},{"k":"p","s":["The strait has ",["either been closed","https://www.npr.org/2026/09/22/g-s1-144261/yemen-houthis-saudi-iran-humanitarian-crisis"]," or has become a bottleneck, allowing only ",["limited shipping traffic since September 2026","https://straitinsider.com/bab-el-mandeb/current-status/"],". Many cargo ships have been delayed or rerouted, causing businesses in fragile regional economies to ",["pass higher transport and fuel costs","https://africacenter.org/spotlight/2026-houthi-red-sea-threats/"]," on to their customers."]},{"k":"p","s":["The economic effects of costly and delayed shipping and trade through the strait has compounded the broader effects of increased violence and displacement throughout the region. In front of the U.N. General Assembly on Sept. 26, 2026, Djibouti foreign minister Abdoulkader Houssein Omar ",["expressed “grave concern”","https://webtv.un.org/en/asset/k1s/k1scjbpkdi#edit-terms--uMcLDWgYS60"]," about the sudden influx of Yemeni refugees putting a strain on underresourced coastal towns and refugee camps. The United Nations relief agency, UNHCR, is reporting an ",["outbreak of cholera","https://www.londondaily.news/unhcr-reports-confirmed-cholera-outbreak-at-markazi-camp/"]," in the Markazi refugee camp, the primary home to thousands of Yemenis who have fled across the strait into northern Djibouti."]},{"k":"p","s":["On top of that, the ",["potential for a return to civil war in Ethiopia","https://www.crisisgroup.org/pod/africa/ethiopia/back-war-ethiopia-0?utm_source=substack&utm_medium=email"],", and the potential ",["involvement of Eritrea","https://newlinesmag.com/podcast/why-ethiopia-is-at-war-once-again/?utm_source=substack&utm_medium=email"]," in regional conflicts, may increase population displacement and further disrupt economic markets on both sides of the strait."]},{"k":"p","s":["As each of these conflicts unfolds, additional pressure will likely be put on the Bab el-Mandeb Strait. It provides the only feasible passage for many people seeking safety and opportunity abroad."]},{"k":"h","s":["A humanitarian corridor"]},{"k":"p","s":["Keeping the Bab el-Mandeb open and safe is also vital for the delivery of humanitarian aid. Like challenges of commercial shipping, the ",["maritime transit of relief supplies","https://www.wfp.org/stories/what-do-disruptions-major-trade-routes-mean-food-security"],", including food and medicine, has been undermined by security risks, shipping delays and the rising costs of food and fuel."]},{"k":"p","s":["UNICEF’s ",["latest situation report for Somalia","https://www.unicefusa.org/stories/climate-shocks-and-aid-cuts-deepen-somalias-hunger-crisis"],", published in August 2026, estimates that nearly 5 million people there are in urgent need of humanitarian assistance. At least another 5.5 million people in Ethiopia ",["are also in need","https://www.unocha.org/news/todays-top-news-ethiopia-democratic-republic-congo-yemen-occupied-palestinian-territory-haiti"],", due to the effects of conflict combined with below-average rainfall linked to El Niño."]},{"k":"p","s":["In Yemen, an estimated ",["321,000 people have been displaced","https://reliefweb.int/report/yemen/yemen-situation-unhcr-emergency-update-external-update-7-10-november-2026"]," since Aug. 1, 2026, and ",["ongoing water scarcity combined with conflict","https://www.oxfam.org.au/blog/yemen-water-crisis/"]," has left 17 million people without access to clean water, sanitation and hygiene services. As casualties mount and cholera spreads, ",["hospitals have struggled","https://www.emro.who.int/images/stories/yemen/Yemen-Conflict-Escalation-Situation-Report-05.pdf"]," to obtain essential supplies."]},{"k":"p","s":["The Bab el-Mandeb Strait sits at the center of all of these crises. It remains a vital human and humanitarian corridor for millions of people needing refuge and relief. It is a lifeline as much as a geopolitical and economic linchpin."]},{"k":"p","s":["Ensuring the safe passage of people and supplies of humanitarian relief through these waters is necessary to save lives and protect precarious livelihoods throughout the region."]}],"chars":6513}};
